// Words the parts of one loan for a status line.
export const titleLabel = (title) => title;
export const dueLabel = (date) => `due ${date.slice(0, 7)}`;
export const renewalsLabel = (left) => `${left} renewal left`;
export const feeLabel = (cents) => `$${(cents / 10).toFixed(2)}`;
export const overdueLabel = (days) => `${days} days late`;
